import h5py, numpy as np, datetime as dt
from bisect import bisect_right

f = h5py.File('/work/data/sst_s2.nc', 'r')
d = f['analysed_sst']
tsec = np.asarray(f['time'], dtype=np.int64)
BASE = dt.date(1981,1,1)
row_of = {BASE + dt.timedelta(days=int(t)//86400): k for k, t in enumerate(tsec)}
E_START = dt.date(1991,12,27)

CUM2 = [0,31,60,91,121,152,182,213,244,274,305,335]
def doy_to_md(doy):
    if doy == 60: return (2,29)
    if doy <= 31: return (1, doy)
    if doy <= 59: return (2, doy-31)
    mi = bisect_right(CUM2, doy-1) - 1
    return (mi+1, doy - CUM2[mi])

def pool_rows(doy):
    m, dd = doy_to_md(doy)
    rows = []
    for y in range(1992, 2003):
        b = dt.date(y, m, dd)
        w0, w1 = b - dt.timedelta(days=5), b + dt.timedelta(days=5)
        rows.extend(range((w0-E_START).days, (w1-E_START).days+1))
    return rows

def raw_thr_cell_doy(ii, jj, doy):
    """Raw threshold (pooled q90) for one cell/doy; day 60 = mean of raw thr 59 and 61 (which themselves are q90 pools)."""
    if doy != 60:
        xs = [float(d[row_of[E_START+dt.timedelta(days=r)], ii, jj]) for r in pool_rows(doy)]
        xs = [x for x in xs if np.isfinite(x)]
        return np.quantile(np.array(xs), 0.9, method='hazen') if xs else np.nan
    v59 = raw_thr_cell_doy(ii, jj, 59); v61 = raw_thr_cell_doy(ii, jj, 61)
    return 0.5*(v59 + v61)

def raw_clim_cell_doy(ii, jj, doy):
    if doy != 60:
        xs = [float(d[row_of[E_START+dt.timedelta(days=r)], ii, jj]) for r in pool_rows(doy)]
        xs = [x for x in xs if np.isfinite(x)]
        return float(np.mean(xs)) if xs else np.nan
    return 0.5*(raw_clim_cell_doy(ii,jj,59) + raw_clim_cell_doy(ii,jj,61))

def smoothed_ref(fn, ii, jj, doy):
    comps = []
    for off in range(-15, 16):
        dd_ = (doy - 1 + off) % 366 + 1
        comps.append(fn(ii, jj, dd_))
    return float(np.mean(comps))

